FA = '۰۱۲۳۴۵۶۷۸۹'

def fa_digits(text):
    """Persian digits for plain numbers; tokens with Latin letters (L90, H4, SLX) stay as they are."""
    def tok(t):
        return t if re.search(r'[A-Za-z]', t) else re.sub(r'\d', lambda m: FA[int(m.group())], t)
    return ' '.join(tok(t) for t in text.split(' '))

def en_digits(text):
    return re.sub('[۰-۹]', lambda m: str(FA.index(m.group())), text)

