COMPAT_TIP = 'برای اطمینان از سازگاری، پیش از خرید شکل قطعه و فیش آن را با نمونه‌ی روی خودرو مقایسه کنید یا با پشتیبانی آریزون یدک تماس بگیرید.'

def part_type(name):
    for rx, label, what, why in TYPES:
        if re.search(rx, name):
            return label, what, why
    return None

NUMS = {'یک': 1, 'دو': 2, 'سه': 3, 'چهار': 4, 'پنج': 5, 'شش': 6, 'ده': 10}
COLORS = ['مشکی', 'خاکستری', 'سفید', 'زرد', 'سبز', 'قهوه ای', 'صورتی', 'طوسی', 'آبی', 'قرمز']

def specs_for(name, label, cars, kit):
    n = en_digits(name)
    sp = [('نوع قطعه', label)]
    if re.search(r'ایربگ', n):
        if re.search(r'ایربگ (چپ|فرمان)', n): sp.append(('محل نصب', 'سمت راننده (غربیلک فرمان)'))
        elif re.search(r'ایربگ راست|سرنشین', n): sp.append(('محل نصب', 'سمت سرنشین (داشبورد)'))
        if 'بدون قاب' in n: sp.append(('قاب', 'بدون قاب'))
    if 'مادگی' in n: sp.append(('نوع اتصال', 'مادگی'))
    elif 'نری' in n: sp.append(('نوع اتصال', 'نری'))
    pins = re.findall(r'(\d+|یک|دو|سه|چهار|پنج|شش|ده) ?فیش', n)
    if len(pins) == 1:
        v = pins[0]; v = int(v) if v.isdigit() else NUMS[v]
        sp.append(('تعداد فیش', fa_digits(str(v))))
    if re.search(r'سیم ?دار', n): sp.append(('سیم', 'سیم‌دار'))
    elif re.search(r'بی ?سیم', n): sp.append(('سیم', 'بدون سیم'))
    m = re.search(r'تیپ ?([25])', n)
    if m: sp.append(('تیپ موتور', f'تیپ {FA[int(m.group(1))]}'))
    if re.search(r'یورو ?4', n): sp.append(('استاندارد', 'یورو ۴'))
    if 'ABS' not in n:
        for k, v in (('زیمنس', 'زیمنس'), ('ساژم', 'ساژم'), ('SSAT', 'SSAT'), ('بوش', 'بوش')):
            if k in n: sp.append(('سیستم انژکتور', v)); break
    if re.search(r'قدیم', n) and not re.search(r'جدید', n): sp.append(('مدل', 'قدیم'))
    elif re.search(r'جدید', n) and not re.search(r'قدیم', n): sp.append(('مدل', 'جدید'))
    if re.search(r'ایربگ|رله|قاب|سیم اکسیژن', n):
        for c in COLORS:
            if c in n: sp.append(('رنگ', c.replace('قهوه ای', 'قهوه‌ای'))); break
    if kit: sp.append(('محتوای بسته', 'مجموعه (چند قطعه در یک بسته)'))
    return sp

def describe(name, label, what, why, cars, kit):
    title = fa_digits(name)
    lines = [f'{what} {why}']
    if kit:
        lines.append('این محصول به‌صورت مجموعه عرضه می‌شود و تمام قطعات نمایش داده‌شده در تصویر اصلی را شامل می‌شود.')
    lines.append(COMPAT_TIP)
    return '\n'.join(lines)

# ───────────────────────── build ─────────────────────────
SITE_NAME = {325: 'شیر فرمان', 324: 'شیر فرمان ال 90', 162: 'خار سوکت کامپیوتر'}

def build():
    info = json.load(open(S + '/srcinfo.json'))
    import sys; sys.path.insert(0, '/root/work')
    from products import products
    prods = {p['id']: p for p in products()}
    done = {}
    for root, _, fs in os.walk(OUT):
        if '.done' in fs:
            d = json.load(open(os.path.join(root, '.done')))
            done[d['id']] = [os.path.join(root, f) for f in d['files']]
    items, missing = [], []
    for i, p in sorted(prods.items()):
        if i in DROP_DUP or i in MERGE_INTO:
            continue
        folder = info[str(i)]['f'].split('/')[0]
        folder = {'مغزی پمپ وسوخت رسانی': 'مغزی پمپ و سوخت رسانی'}.get(folder, folder).strip()
        main, sub, _ = FOLDERS[folder]
        if i in MOVE_TO_MAIN: main, sub = MOVE_TO_MAIN[i], None
        name = SITE_NAME.get(i, p['name'])
        pt = part_type(name)
        if not pt:
            missing.append((i, name)); continue
        label, what, why = pt
        cars = cars_for(name)
        imgs = list(done[i])
        for src, dst in MERGE_INTO.items():
            if dst == i: imgs.append(done[src][0])
        kit = bool(p['kit'] and not p['same'])
        items.append(dict(
            id=i, sku=f'AY-{1000 + i}', name=fa_digits(name), main=main, sub=sub,
            cars=cars, description=describe(name, label, what, why, cars, kit),
            specs='\n'.join(f'{a}: {b}' for a, b in specs_for(name, label, cars, kit)),
            images=imgs[:8], src_folder=folder,
        ))
    return items, missing

def category_tree():
    tree = {m[0]: dict(icon=m[1], description=m[2], subs={}) for m in MAINS}
    for folder, (main, sub, desc) in FOLDERS.items():
        if sub: tree[main]['subs'][sub] = desc
    return tree

if __name__ == '__main__':
    items, missing = build()
    print('products', len(items), 'missing type', missing)
    json.dump(dict(items=items, tree=category_tree(), cars=[dict(make=c[0], name=c[1]) for c in CARS]),
              open(S + '/site_import.json', 'w'), ensure_ascii=False, indent=1)
    from collections import Counter
    print(Counter((it['main'], it['sub']) for it in items).most_common(60))
    print('no cars:', sum(1 for it in items if not it['cars']))
    print('images', sum(len(it['images']) for it in items))
